// edit the file in main/ and run the script again.
// imu.cpp - IMU task
//
// Every 10 ms (SAMPLE_HZ) this task:
//   1. reads the buttons (M5.update()) and turns presses into ev_* flags for main.cpp,
//   2. reads acceleration (g) and angular velocity (deg/s) from the BMI270 via M5Unified,
//   3. integrates the angles shown on the Gyro and Orient pages: per-axis theta, a gyro-only
//      quaternion, and a fused quaternion (Mahony filter: gyro corrected by gravity),
//   4. handles zeroing (gyro offset measurement) and recording,
//   5. appends the sample to the live ring buffer for the web stream,
//   6. publishes a consistent copy of everything for other tasks (imu_view()).
//
// Keeping all I2C traffic on this one task avoids two tasks using the bus at the same time.
//
// Axes: M5Unified rotates the BMI270's chip axes for the StickS3 (X = chip +Y, Y = chip -X,
// Z = chip +Z), so the X/Y/Z here are M5Unified's StickS3 axes, not the datasheet's chip axes.
#include <cmath>
#include <cstring>
#include <M5Unified.h>
#include "esp_heap_caps.h"
#include "esp_timer.h"
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "app.h"

std::atomic<bool> ev_key1_click{false}, ev_key1_hold{false}, ev_key2_click{false};
Sample live_ring[LIVE_N];
std::atomic<uint32_t> live_head{0};

// Snapshot shared with other tasks; guarded by a spinlock because ImuView is larger than an atomic.
static portMUX_TYPE s_lock = portMUX_INITIALIZER_UNLOCKED;
static ImuView s_view = {};

static constexpr float DEG = 180.0f / (float)M_PI;
static constexpr int   ZERO_SAMPLES = SAMPLE_HZ;  // zeroing averages 1 s of gyro readings
static constexpr float STILL_LIMIT  = 2.0f;       // deg/s; a larger standard deviation means "moved"

// BMI270 register settings (datasheet ACC_CONF, address 0x40). The reset value 0xA8 is
// 100 Hz, the same as our polling rate, so the two clocks drift and a poll sometimes finds
// no new reading (value repeated) or misses one. 0xA9 = 200 Hz, performance filter, normal
// bandwidth: every 10 ms poll then normally sees a reading at most 5 ms old.
// The gyroscope already defaults to 200 Hz (GYR_CONF 0xA9).
static constexpr uint8_t BMI270_ADDR = 0x68;      // StickS3 internal I2C bus
static constexpr uint8_t ACC_CONF    = 0x40;
static constexpr uint8_t ACC_CONF_200HZ = 0xA9;

static std::atomic<uint32_t> s_stale{0};          // polls without new accelerometer data
static bool s_acc_200hz = false;                  // ACC_CONF confirmed at 0xA9

// Zeroing state. main.cpp resets the sums, then sets s_zero_state = 0; this task only
// touches the sums while the state is 0, so the atomic store orders the hand-over.
static std::atomic<int> s_zero_state{1};          // 0 busy, 1 done, 2 moved
static double s_sum[3], s_sq[3], s_acc[3];          // gyro sums, squares; accelerometer sums
static int    s_zero_n;

// Recording buffer (PSRAM) and progress.
static Sample* s_rec = nullptr;
static std::atomic<int>  s_rec_n{0};
static std::atomic<int>  s_rec_target{0};
static std::atomic<bool> s_rec_on{false};
static int64_t s_rec_t0;                          // esp_timer time of the first recorded sample

// Sensor fusion (Mahony complementary filter, proportional term only).
// The accelerometer's reading at rest points "up" (it measures f = a - g). The filter compares
// that direction with the "up" predicted by the fused quaternion and turns the gyro rate a
// little toward agreement (gain FUSION_KP, time constant about 1/KP s). This removes drift in
// roll and pitch; yaw (heading) cannot be corrected without a magnetometer and still drifts.
// The correction is skipped while |f| is far from 1 g, i.e. while the device accelerates,
// because the reading then is not just gravity.
static constexpr float FUSION_KP   = 1.0f;          // 1/s
static constexpr float FUSION_GATE = 0.15f;         // g: use the accelerometer only if ||f| - 1| < this

// Orientation with the given tilt and yaw = 0, from an accelerometer reading at rest
// (Z-Y-X convention: q = q_y(pitch) * q_x(roll)). At rest f = g * (-sin p, cos p sin r, cos p cos r).
static void quat_from_tilt(float* q, float fx, float fy, float fz)
{
    const float roll  = std::atan2(fy, fz);
    const float pitch = std::atan2(-fx, std::sqrt(fy * fy + fz * fz));
    const float cr = std::cos(roll / 2), sr = std::sin(roll / 2);
    const float cp = std::cos(pitch / 2), sp = std::sin(pitch / 2);
    q[0] = cp * cr; q[1] = cp * sr; q[2] = sp * cr; q[3] = -sp * sr;
}

// Correction rate (deg/s, body axes) that turns the fused estimate toward the measured "up".
static void fusion_correction(const float* q, const Sample& s, float* corr)
{
    corr[0] = corr[1] = corr[2] = 0;
    const float n = std::sqrt(s.ax * s.ax + s.ay * s.ay + s.az * s.az);
    if (std::fabs(n - 1.0f) > FUSION_GATE) return;            // accelerating: trust the gyro
    const float ax = s.ax / n, ay = s.ay / n, az = s.az / n;   // measured up, body frame
    // Predicted up in body frame = third row of the rotation matrix of q
    const float vx = 2 * (q[1] * q[3] - q[0] * q[2]);
    const float vy = 2 * (q[0] * q[1] + q[2] * q[3]);
    const float vz = q[0] * q[0] - q[1] * q[1] - q[2] * q[2] + q[3] * q[3];
    // Error = measured x predicted: the rotation that would bring them together
    corr[0] = FUSION_KP * (ay * vz - az * vy) * DEG;
    corr[1] = FUSION_KP * (az * vx - ax * vz) * DEG;
    corr[2] = FUSION_KP * (ax * vy - ay * vx) * DEG;
}

// Apply one gyro sample to the orientation quaternion: q = q * dq.
// w* are angular velocities in deg/s (offset removed) in the device's own axes, dt in s.
// dq is the rotation by angle |w| dt about the axis w / |w|. Multiplying on the right
// applies it in the body frame, in the order the samples arrive, so any rotation is handled.
static void quat_step(float* q, float wx, float wy, float wz, float dt)
{
    const float rx = wx / DEG, ry = wy / DEG, rz = wz / DEG;      // rad/s
    const float rate = std::sqrt(rx * rx + ry * ry + rz * rz);
    const float angle = rate * dt;
    if (angle < 1e-9f) return;                                   // no measurable rotation
    const float s = std::sin(angle / 2) / rate;
    const float d[4] = {std::cos(angle / 2), rx * s, ry * s, rz * s};
    const float r[4] = {
        q[0] * d[0] - q[1] * d[1] - q[2] * d[2] - q[3] * d[3],
        q[0] * d[1] + q[1] * d[0] + q[2] * d[3] - q[3] * d[2],
        q[0] * d[2] - q[1] * d[3] + q[2] * d[0] + q[3] * d[1],
        q[0] * d[3] + q[1] * d[2] - q[2] * d[1] + q[3] * d[0],
    };
    const float n = std::sqrt(r[0] * r[0] + r[1] * r[1] + r[2] * r[2] + r[3] * r[3]);
    for (int i = 0; i < 4; i++) q[i] = r[i] / n;                 // renormalise against rounding drift
}

static void imu_task(void*)
{
    ImuView v = {};
    v.q[0] = 1;                                                  // identity: no rotation yet
    {
        // Start the fused orientation from the current tilt (yaw 0); the filter refines it.
        Sample s0;
        M5.Imu.update();
        M5.Imu.getAccel(&s0.ax, &s0.ay, &s0.az);
        quat_from_tilt(v.qf, s0.ax, s0.ay, s0.az);
    }
    int64_t prev_us = esp_timer_get_time();
    TickType_t wake = xTaskGetTickCount();

    while (true) {
        // Fixed-rate loop: vTaskDelayUntil keeps a steady period even if one pass runs long.
        vTaskDelayUntil(&wake, pdMS_TO_TICKS(1000 / SAMPLE_HZ));

        // Buttons. Clicks fire on release; a hold fires once after M5Unified's hold time.
        M5.update();
        if (M5.BtnA.wasHold())    ev_key1_hold  = true;
        if (M5.BtnA.wasClicked()) ev_key1_click = true;
        if (M5.BtnB.wasClicked()) ev_key2_click = true;

        // Read the IMU and measure the real time step for integration. update() reports which
        // sensors had new data; without new accelerometer data getAccel() repeats the last value.
        const auto fresh = M5.Imu.update();
        if (!(fresh & m5::IMU_Class::sensor_mask_accel)) s_stale++;
        const int64_t now = esp_timer_get_time();
        const float dt = (now - prev_us) * 1e-6f;
        prev_us = now;

        Sample s;
        s.t_ms = (uint32_t)(now / 1000);
        M5.Imu.getAccel(&s.ax, &s.ay, &s.az);                    // g
        M5.Imu.getGyro(&s.wx, &s.wy, &s.wz);                     // deg/s
        v.s = s;

        // Angles for the Gyro and Orient pages, from the offset-corrected rates.
        // Skip unusually long gaps (> 0.1 s) rather than integrating a large error.
        const float w[3] = {s.wx - v.bias[0], s.wy - v.bias[1], s.wz - v.bias[2]};
        if (dt < 0.1f) {
            for (int i = 0; i < 3; i++) v.theta[i] += w[i] * dt;  // per-axis theta = integral of omega dt
            quat_step(v.q, w[0], w[1], w[2], dt);                // gyro-only 3-D orientation
            float c[3];
            fusion_correction(v.qf, s, c);                       // fused: gyro + gravity
            quat_step(v.qf, w[0] + c[0], w[1] + c[1], w[2] + c[2], dt);
        }

        // Zeroing: average 1 s of raw gyro readings. If the spread is small the device was
        // still, so the mean is the offset; then reset the angles and the orientation. The
        // fused orientation is set to the measured tilt (mean accelerometer) with yaw = 0.
        if (s_zero_state == 0) {
            const float g[3] = {s.wx, s.wy, s.wz};
            const float f[3] = {s.ax, s.ay, s.az};
            for (int i = 0; i < 3; i++) {
                s_sum[i] += g[i]; s_sq[i] += (double)g[i] * g[i]; s_acc[i] += f[i];
            }
            if (++s_zero_n >= ZERO_SAMPLES) {
                bool still = true;
                float mean[3];
                for (int i = 0; i < 3; i++) {
                    mean[i] = s_sum[i] / s_zero_n;
                    const double var = s_sq[i] / s_zero_n - (double)mean[i] * mean[i];
                    if (std::sqrt(std::fmax(0.0, var)) > STILL_LIMIT) still = false;
                }
                if (still) {
                    for (int i = 0; i < 3; i++) { v.bias[i] = mean[i]; v.theta[i] = 0; }
                    v.q[0] = 1; v.q[1] = v.q[2] = v.q[3] = 0;
                    quat_from_tilt(v.qf, s_acc[0] / s_zero_n, s_acc[1] / s_zero_n, s_acc[2] / s_zero_n);
                }
                s_zero_state = still ? 1 : 2;
            }
        }

        // Recording: store samples with time measured from the first recorded sample.
        if (s_rec_on) {
            const int n = s_rec_n;
            if (n == 0) s_rec_t0 = now;
            Sample r = s;
            r.t_ms = (uint32_t)((now - s_rec_t0) / 1000);
            s_rec[n] = r;
            s_rec_n = n + 1;
            if (n + 1 >= s_rec_target) s_rec_on = false;          // done; main.cpp saves the file
        }

        // Live ring buffer: write the slot first, then publish it by advancing the head.
        const uint32_t h = live_head;
        live_ring[h % LIVE_N] = s;
        live_head = h + 1;

        // Publish the snapshot for the screen and the web status line.
        taskENTER_CRITICAL(&s_lock);
        s_view = v;
        taskEXIT_CRITICAL(&s_lock);
    }
}

bool imu_start(void)
{
    // M5.begin() gives M5Unified's IMU class an offset per axis: saved offsets if it can load
    // them, otherwise a snapshot of the first reading at power-on (wrong if the StickS3 was
    // moving or tilted then). Clear them so every value is what the BMI270 itself reports:
    // the worksheet asks students to find the sensor's own offsets, and KEY1 zeroing measures
    // the gyro offset for the angle pages separately.
    M5.Imu.clearOffsetData();

    // Accelerometer to 200 Hz (see ACC_CONF_200HZ). Read back to confirm, with one retry.
    // A failure is not fatal (the data is still valid at 100 Hz) but is reported through
    // imu_accel_200hz(): main.cpp shows a warning and the web page's sampling check flags it.
    uint8_t acc_conf = 0;
    for (int attempt = 0; attempt < 2 && acc_conf != ACC_CONF_200HZ; attempt++) {
        M5.In_I2C.writeRegister8(BMI270_ADDR, ACC_CONF, ACC_CONF_200HZ, 400000);
        acc_conf = M5.In_I2C.readRegister8(BMI270_ADDR, ACC_CONF, 400000);
    }
    s_acc_200hz = (acc_conf == ACC_CONF_200HZ);
    printf("# BMI270 ACC_CONF = 0x%02X%s\n", acc_conf, s_acc_200hz ? "" : " (expected 0xA9: accelerometer not at 200 Hz)");

    // MAX_REC_S * SAMPLE_HZ samples of 28 bytes = 168 KB, so use PSRAM.
    s_rec = (Sample*)heap_caps_malloc(sizeof(Sample) * MAX_REC_S * SAMPLE_HZ, MALLOC_CAP_SPIRAM);
    // Priority 10 on core 1: above the UI (main task) and the web server, away from Wi-Fi on core 0.
    return xTaskCreatePinnedToCore(imu_task, "imu", 4096, nullptr, 10, nullptr, 1) == pdPASS;
}

uint32_t imu_stale_reads(void) { return s_stale; }
bool     imu_accel_200hz(void)  { return s_acc_200hz; }

void imu_view(ImuView* out)
{
    taskENTER_CRITICAL(&s_lock);
    *out = s_view;
    taskEXIT_CRITICAL(&s_lock);
}

void imu_request_zero(void)
{
    memset(s_sum, 0, sizeof(s_sum));
    memset(s_sq, 0, sizeof(s_sq));
    memset(s_acc, 0, sizeof(s_acc));
    s_zero_n = 0;
    s_zero_state = 0;                                            // hand over to the IMU task
}

int imu_zero_result(void) { return s_zero_state; }

bool imu_rec_start(int seconds)
{
    if (!s_rec || s_rec_on || seconds < 1 || seconds > MAX_REC_S) return false;
    s_rec_target = seconds * SAMPLE_HZ;
    s_rec_n = 0;
    s_rec_on = true;                                             // set last: starts the IMU task recording
    return true;
}

bool          imu_rec_running(void) { return s_rec_on; }
int           imu_rec_count(void)   { return s_rec_n; }
int           imu_rec_target(void)  { return s_rec_target; }
const Sample* imu_rec_data(void)    { return s_rec; }
